import { lookup } from 'node:dns/promises';
import { NextResponse } from 'next/server';

const MAX_BYTES = 100_000;

function isPrivateIp(ip: string): boolean {
  if (ip.startsWith('::ffff:')) ip = ip.slice(7);
  if (ip.includes(':')) {
    const lower = ip.toLowerCase();
    return lower === '::1' || lower.startsWith('fc') || lower.startsWith('fd') || lower.startsWith('fe8') || lower.startsWith('fe9') || lower.startsWith('fea') || lower.startsWith('feb');
  }
  const [a, b] = ip.split('.').map(Number);
  return a === 10 || a === 127 || a === 0 || (a === 169 && b === 254) || (a === 172 && b >= 16 && b <= 31) || (a === 192 && b === 168);
}

// Blocks requests to private/loopback/link-local addresses to prevent SSRF.
async function assertSafeUrl(url: URL) {
  if (url.protocol !== 'http:' && url.protocol !== 'https:') throw new Error('Only http/https URLs are allowed');
  const { address } = await lookup(url.hostname);
  if (isPrivateIp(address)) throw new Error('URL resolves to a disallowed address');
}

export async function POST(request: Request) {
  const { url } = await request.json().catch(() => ({ url: undefined }));
  if (typeof url !== 'string') return NextResponse.json({ error: 'url is required' }, { status: 400 });

  let parsed: URL;
  try {
    parsed = new URL(url);
    await assertSafeUrl(parsed);
  } catch {
    return NextResponse.json({ error: 'Invalid or disallowed url' }, { status: 400 });
  }

  let response: Response;
  try {
    response = await fetch(parsed, { redirect: 'error', signal: AbortSignal.timeout(5000) });
  } catch {
    return NextResponse.json({ error: 'Failed to fetch url' }, { status: 502 });
  }
  if (!response.ok || !response.body) return NextResponse.json({ error: 'Failed to fetch url' }, { status: 502 });

  const reader = response.body.getReader();
  let html = '';
  let received = 0;
  while (received < MAX_BYTES) {
    const { done, value } = await reader.read();
    if (done) break;
    received += value.length;
    html += Buffer.from(value).toString('utf8');
    if (/<\/title>/i.test(html)) break;
  }
  reader.cancel().catch(() => {});

  const title = html.match(/<title[^>]*>([^<]*)<\/title>/i)?.[1]?.trim() ?? '';
  return NextResponse.json({ title });
}

